import React, { useState, useEffect } from 'react';
import api from '../../services/api';
import { formatDate } from '../../utils/dateHelpers';

export default function Profile() {
  const [history, setHistory] = useState([]);

  useEffect(() => {
    api.get('/transactions/borrow/my_borrows/').then(({ data }) => setHistory(data.results || data));
  }, []);

  return (
    <div className="profile-page">
      <h2>My Borrowing History</h2>
      <table>
        <thead>
          <tr><th>Book</th><th>Issue Date</th><th>Due Date</th><th>Return Date</th><th>Status</th></tr>
        </thead>
        <tbody>
          {history.map((t) => (
            <tr key={t.id}>
              <td>{t.book_title}</td>
              <td>{formatDate(t.issue_date)}</td>
              <td>{formatDate(t.due_date)}</td>
              <td>{t.return_date ? formatDate(t.return_date) : '-'}</td>
              <td>{t.status}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}
